def _normalize_name(value: str) -> str:
    return " ".join(str(value or "").strip().lower().split())


def _game_config(name: str, genetics: str) -> dict:
    key = _normalize_name(name)
    checksum = zlib.crc32(key.encode("utf-8")) & 0xFFFFFFFF
    level = 1 + (checksum % 50)
    jitter = ((checksum >> 8) % 21) - 10

    base_value = max(15, int(round((15 + (level * level * 1.10) + jitter * 2) / 5.0) * 5))
    grow_time = max(300, min(55_000, 300 + level * 1_090 + jitter * 18))
    low_yield = max(5, int(round(5 + level * 2.05 + jitter * 0.12)))
    high_yield = max(low_yield + 1, int(round(low_yield * 2.0)))

    genetics_label = genetics if genetics in {"Indica", "Sativa", "Hybrid"} else "Hybrid"
    return {
        "time": int(grow_time),
        "base_value": int(base_value),
        "yield": (int(low_yield), int(high_yield)),
        "level_req": int(level),
        "genetics": [genetics_label],
        "display_name": str(name).strip(),
        "catalog": "expanded",
    }


def _build_growth_cycles() -> dict[str, dict]:
    catalog = {key: dict(value) for key, value in LEGACY_GROWTH_CYCLES.items()}
    for raw in _RAW_EXPANDED_CATALOG.splitlines():
        raw = raw.strip()
        if not raw or "|" not in raw:
            continue
        display_name, genetics = raw.rsplit("|", 1)
        key = _normalize_name(display_name)
        if not key or key in catalog:
            continue
        catalog[key] = _game_config(display_name, genetics)
    return catalog


GROWTH_CYCLES = _build_growth_cycles()


def seed_shop_item(strain_key: str, config: dict) -> dict:
    level = max(1, int(config.get("level_req", 1) or 1))
    base_value = max(15, int(config.get("base_value", 15) or 15))
    raw_cost = base_value * (3.0 + level / 10.0)
    cost = max(15, int(round(raw_cost / 5.0) * 5))
    return {
        "type": "seed",
        "cost": cost,
        "description": f"Seed for {config.get('display_name', strain_key.title())}. Game-balanced catalog strain.",
        "level_req": level,
        "strain_key": strain_key,
        "catalog": config.get("catalog", "legacy"),
    }


def generated_seed_shop_items() -> dict[str, dict]:
    return {
        f"{strain_key} seed": seed_shop_item(strain_key, config)
        for strain_key, config in GROWTH_CYCLES.items()
    }


EXPANDED_STRAIN_COUNT = len(GROWTH_CYCLES)
